-- VNV Events Pasta Station location cycle, local batch 02 (cities 16-30).
SET NAMES utf8mb4;
DELIMITER $$
DROP PROCEDURE IF EXISTS vnv_pasta_b02_preflight$$
CREATE PROCEDURE vnv_pasta_b02_preflight() BEGIN
IF DATABASE()<>'ophyra' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Wrong local database'; END IF;
IF (SELECT COUNT(*) FROM cms_contents WHERE id_owner=2 AND site_key='vnvevents' AND slug IN ('pasta-station-catering-delray-beach','pasta-station-catering-wellington','pasta-station-catering-palm-beach-gardens','pasta-station-catering-jupiter','pasta-station-catering-royal-palm-beach','pasta-station-catering-west-palm-beach','pasta-station-catering-lazy-lake','pasta-station-catering-miami','pasta-station-catering-coral-gables','pasta-station-catering-doral','pasta-station-catering-kendall','pasta-station-catering-miami-lakes','pasta-station-catering-cutler-bay','pasta-station-catering-pinecrest','pasta-station-catering-south-miami'))>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Pasta content collision'; END IF;
IF (SELECT COUNT(*) FROM cms_routes WHERE id_owner=2 AND site_key='vnvevents' AND route IN ('/locations/pasta-station-catering-delray-beach/','/locations/pasta-station-catering-wellington/','/locations/pasta-station-catering-palm-beach-gardens/','/locations/pasta-station-catering-jupiter/','/locations/pasta-station-catering-royal-palm-beach/','/locations/pasta-station-catering-west-palm-beach/','/locations/pasta-station-catering-lazy-lake/','/locations/pasta-station-catering-miami/','/locations/pasta-station-catering-coral-gables/','/locations/pasta-station-catering-doral/','/locations/pasta-station-catering-kendall/','/locations/pasta-station-catering-miami-lakes/','/locations/pasta-station-catering-cutler-bay/','/locations/pasta-station-catering-pinecrest/','/locations/pasta-station-catering-south-miami/'))>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Pasta route collision'; END IF;
END$$
CALL vnv_pasta_b02_preflight()$$
DROP PROCEDURE vnv_pasta_b02_preflight$$
DELIMITER ;
SELECT id INTO @vnv_template_id FROM cms_templates WHERE id_owner=2 AND site_key='vnvevents' AND template_key='local-location-page' AND status='ACTIVE' LIMIT 1;
SELECT id INTO @vnv_category_id FROM cms_categories WHERE id_owner=2 AND site_key='vnvevents' AND slug='catering-services' AND is_active=1 AND applies_to_locations=1 LIMIT 1;
START TRANSACTION;
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
COMMIT;
SELECT COUNT(*) AS pasta_batch_01_contents FROM cms_contents WHERE id_owner=2 AND site_key='vnvevents' AND slug IN ('pasta-station-catering-delray-beach','pasta-station-catering-wellington','pasta-station-catering-palm-beach-gardens','pasta-station-catering-jupiter','pasta-station-catering-royal-palm-beach','pasta-station-catering-west-palm-beach','pasta-station-catering-lazy-lake','pasta-station-catering-miami','pasta-station-catering-coral-gables','pasta-station-catering-doral','pasta-station-catering-kendall','pasta-station-catering-miami-lakes','pasta-station-catering-cutler-bay','pasta-station-catering-pinecrest','pasta-station-catering-south-miami');
SELECT COUNT(*) AS pasta_batch_01_routes FROM cms_routes WHERE id_owner=2 AND site_key='vnvevents' AND route IN ('/locations/pasta-station-catering-delray-beach/','/locations/pasta-station-catering-wellington/','/locations/pasta-station-catering-palm-beach-gardens/','/locations/pasta-station-catering-jupiter/','/locations/pasta-station-catering-royal-palm-beach/','/locations/pasta-station-catering-west-palm-beach/','/locations/pasta-station-catering-lazy-lake/','/locations/pasta-station-catering-miami/','/locations/pasta-station-catering-coral-gables/','/locations/pasta-station-catering-doral/','/locations/pasta-station-catering-kendall/','/locations/pasta-station-catering-miami-lakes/','/locations/pasta-station-catering-cutler-bay/','/locations/pasta-station-catering-pinecrest/','/locations/pasta-station-catering-south-miami/') AND status='ACTIVE';
